import { useEffect, useState } from "react";
import { base44 } from "@/api/base44Client";
import { Plus, Clock, Users, Trash2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { BELT_ORDER } from "../utils/beltUtils";
import { toast } from "sonner";

const LEVELS = ["Beginner", "Intermediate", "Advanced", "All Levels"];
const DAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
const LEVEL_COLORS = { Beginner: "bg-green-100 text-green-700", Intermediate: "bg-blue-100 text-blue-700", Advanced: "bg-red-100 text-red-700", "All Levels": "bg-purple-100 text-purple-700" };

export default function Classes() {
  const [classes, setClasses] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [loading, setLoading] = useState(true);
  const [form, setForm] = useState({ name: "", level: "Beginner", instructor_name: "", day_of_week: "Monday", start_time: "09:00", end_time: "10:00", capacity: 20, is_active: true });

  const load = async () => {
    const c = await base44.entities.Class.list();
    setClasses(c);
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const handleCreate = async () => {
    await base44.entities.Class.create(form);
    toast.success("Class created!");
    setShowForm(false);
    setForm({ name: "", level: "Beginner", instructor_name: "", day_of_week: "Monday", start_time: "09:00", end_time: "10:00", capacity: 20, is_active: true });
    load();
  };

  const handleDelete = async (id) => {
    await base44.entities.Class.delete(id);
    load();
  };

  const grouped = DAYS.reduce((acc, day) => {
    acc[day] = classes.filter(c => c.day_of_week === day);
    return acc;
  }, {});

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Classes</h1>
          <p className="text-muted-foreground mt-1">Manage recurring class schedule.</p>
        </div>
        <Button onClick={() => setShowForm(true)} className="gap-2"><Plus className="w-4 h-4" /> Add Class</Button>
      </div>

      {loading ? (
        <div className="flex justify-center py-16"><div className="w-8 h-8 border-4 border-muted border-t-primary rounded-full animate-spin" /></div>
      ) : (
        <div className="space-y-6">
          {DAYS.map(day => {
            const dayClasses = grouped[day];
            if (dayClasses.length === 0) return null;
            return (
              <div key={day}>
                <h2 className="font-semibold text-muted-foreground text-sm uppercase tracking-wider mb-3">{day}</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                  {dayClasses.map(cls => (
                    <div key={cls.id} className="bg-card border border-border rounded-2xl p-5 relative group">
                      <button
                        onClick={() => handleDelete(cls.id)}
                        className="absolute top-3 right-3 p-1.5 rounded-lg opacity-0 group-hover:opacity-100 hover:bg-red-50 hover:text-red-500 text-muted-foreground transition-all"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                      <div className="flex items-start justify-between mb-3">
                        <h3 className="font-semibold">{cls.name}</h3>
                        <span className={`text-xs px-2 py-1 rounded-full font-medium ${LEVEL_COLORS[cls.level] || "bg-muted text-muted-foreground"}`}>{cls.level}</span>
                      </div>
                      <div className="space-y-1.5 text-sm text-muted-foreground">
                        <div className="flex items-center gap-2"><Clock className="w-3.5 h-3.5" />{cls.start_time} – {cls.end_time}</div>
                        {cls.instructor_name && <div className="flex items-center gap-2"><Users className="w-3.5 h-3.5" />{cls.instructor_name}</div>}
                        {cls.capacity && <div>Capacity: {cls.capacity}</div>}
                        {cls.belt_min && <div>Belts: {cls.belt_min} – {cls.belt_max || "Black"}</div>}
                      </div>
                      <div className={`mt-3 w-2 h-2 rounded-full ${cls.is_active ? "bg-green-500" : "bg-gray-300"}`} />
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
          {classes.length === 0 && (
            <div className="bg-card border border-border rounded-2xl p-12 text-center text-muted-foreground">No classes scheduled yet.</div>
          )}
        </div>
      )}

      {showForm && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-card border border-border rounded-2xl w-full max-w-lg p-6">
            <h3 className="font-semibold text-lg mb-4">Add Class</h3>
            <div className="space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <div className="col-span-2">
                  <Label>Class Name</Label>
                  <Input value={form.name} onChange={e => set("name", e.target.value)} className="mt-1" placeholder="e.g. Beginner Taekwondo" />
                </div>
                <div>
                  <Label>Level</Label>
                  <Select value={form.level} onValueChange={v => set("level", v)}>
                    <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                    <SelectContent>{LEVELS.map(l => <SelectItem key={l} value={l}>{l}</SelectItem>)}</SelectContent>
                  </Select>
                </div>
                <div>
                  <Label>Day</Label>
                  <Select value={form.day_of_week} onValueChange={v => set("day_of_week", v)}>
                    <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                    <SelectContent>{DAYS.map(d => <SelectItem key={d} value={d}>{d}</SelectItem>)}</SelectContent>
                  </Select>
                </div>
                <div>
                  <Label>Start Time</Label>
                  <Input type="time" value={form.start_time} onChange={e => set("start_time", e.target.value)} className="mt-1" />
                </div>
                <div>
                  <Label>End Time</Label>
                  <Input type="time" value={form.end_time} onChange={e => set("end_time", e.target.value)} className="mt-1" />
                </div>
                <div>
                  <Label>Instructor</Label>
                  <Input value={form.instructor_name} onChange={e => set("instructor_name", e.target.value)} className="mt-1" />
                </div>
                <div>
                  <Label>Capacity</Label>
                  <Input type="number" value={form.capacity} onChange={e => set("capacity", +e.target.value)} className="mt-1" />
                </div>
              </div>
            </div>
            <div className="flex justify-end gap-3 mt-5">
              <Button variant="outline" onClick={() => setShowForm(false)}>Cancel</Button>
              <Button onClick={handleCreate} disabled={!form.name}>Create Class</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

src/pages/Dashboard.jsx:
import { useEffect, useState } from "react";
import { base44 } from "@/api/base44Client";
import { Link } from "react-router-dom";
import { Users, Award, TrendingUp, CreditCard, AlertTriangle, CheckCircle, ChevronRight, Calendar } from "lucide-react";
import BeltBadge from "../components/BeltBadge";
import { BELT_ORDER, BELT_COLORS, checkEligibility, DEFAULT_BELT_REQUIREMENTS } from "../utils/beltUtils";

export default function Dashboard() {
  const [students, setStudents] = useState([]);
  const [payments, setPayments] = useState([]);
  const [announcements, setAnnouncements] = useState([]);
  const [requirements, setRequirements] = useState(DEFAULT_BELT_REQUIREMENTS);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function load() {
      const [s, p, a, br] = await Promise.all([
        base44.entities.Student.list(),
        base44.entities.Payment.list(),
        base44.entities.Announcement.filter({ is_published: true }, "-created_date", 5),
        base44.entities.BeltRequirement.list(),
      ]);
      setStudents(s);
      setPayments(p);
      setAnnouncements(a);
      if (br.length > 0) {
        const reqMap = {};
        br.forEach(r => { reqMap[r.belt] = r; });
        setRequirements(reqMap);
      }
      setLoading(false);
    }
    load();
  }, []);

  const activeStudents = students.filter(s => s.membership_status === "active");
  const eligible = students.filter(s => {
    const { eligible } = checkEligibility(s, requirements);
    return eligible && s.current_belt !== "Black";
  });
  const overduePayments = payments.filter(p => p.status === "overdue");
  const totalRevenue = payments.filter(p => p.status === "paid").reduce((sum, p) => sum + (p.amount || 0), 0);

  const beltDistribution = BELT_ORDER.map(belt => ({
    belt,
    count: students.filter(s => s.current_belt === belt).length,
  })).filter(b => b.count > 0);

  const recentEligible = eligible.slice(0, 5);

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="w-8 h-8 border-4 border-muted border-t-primary rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-3xl font-bold tracking-tight">Dashboard</h1>
        <p className="text-muted-foreground mt-1">Welcome back — here's your dojo at a glance.</p>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
        <StatCard icon={Users} label="Active Students" value={activeStudents.length} color="blue" />
        <StatCard icon={Award} label="Eligible for Promotion" value={eligible.length} color="green" />
        <StatCard icon={CreditCard} label="Total Revenue" value={`$${totalRevenue.toLocaleString()}`} color="purple" />
        <StatCard icon={AlertTriangle} label="Overdue Payments" value={overduePayments.length} color="red" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
        {/* Belt Distribution */}
        <div className="xl:col-span-2 bg-card border border-border rounded-2xl p-6">
          <h2 className="font-semibold text-lg mb-5">Belt Distribution</h2>
          <div className="space-y-3">
            {beltDistribution.map(({ belt, count }) => {
              const colors = BELT_COLORS[belt];
              const pct = students.length > 0 ? (count / students.length) * 100 : 0;
              return (
                <div key={belt} className="flex items-center gap-3">
                  <span className={`w-3 h-3 rounded-full flex-shrink-0 ${colors.dot}`} />
                  <span className="text-sm w-16 font-medium">{belt}</span>
                  <div className="flex-1 h-2.5 bg-muted rounded-full overflow-hidden">
                    <div className={`h-full rounded-full ${colors.dot}`} style={{ width: `${pct}%` }} />
                  </div>
                  <span className="text-sm text-muted-foreground w-8 text-right">{count}</span>
                </div>
              );
            })}
            {beltDistribution.length === 0 && (
              <p className="text-muted-foreground text-sm">No students yet.</p>
            )}
          </div>
        </div>

        {/* Announcements */}
        <div className="bg-card border border-border rounded-2xl p-6">
          <div className="flex items-center justify-between mb-5">
            <h2 className="font-semibold text-lg">Announcements</h2>
            <Link to="/announcements" className="text-xs text-primary hover:underline">View all</Link>
          </div>
          <div className="space-y-3">
            {announcements.length === 0 && <p className="text-muted-foreground text-sm">No announcements.</p>}
            {announcements.map(a => (
              <div key={a.id} className="p-3 bg-muted/50 rounded-xl">
                <p className="text-sm font-medium leading-tight">{a.title}</p>
                <p className="text-xs text-muted-foreground mt-1 line-clamp-2">{a.content}</p>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Eligible for Promotion */}
      <div className="bg-card border border-border rounded-2xl p-6">
        <div className="flex items-center justify-between mb-5">
          <div className="flex items-center gap-2">
            <CheckCircle className="w-5 h-5 text-green-500" />
            <h2 className="font-semibold text-lg">Ready for Promotion</h2>
          </div>
          <Link to="/promotions" className="text-xs text-primary hover:underline flex items-center gap-1">
            View all <ChevronRight className="w-3 h-3" />
          </Link>
        </div>
        {recentEligible.length === 0 ? (
          <p className="text-muted-foreground text-sm">No students currently eligible for promotion.</p>
        ) : (
          <div className="divide-y divide-border">
            {recentEligible.map(s => (
              <div key={s.id} className="py-3 flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-9 h-9 rounded-full bg-muted flex items-center justify-center font-semibold text-sm">
                    {s.full_name?.charAt(0)}
                  </div>
                  <div>
                    <p className="font-medium text-sm">{s.full_name}</p>
                    <p className="text-xs text-muted-foreground">{s.classes_in_current_belt || 0} classes completed</p>
                  </div>
                </div>
                <BeltBadge belt={s.current_belt} size="sm" />
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

function StatCard({ icon: Icon, label, value, color }) {
  const colors = {
    blue: "bg-blue-50 text-blue-600",
    green: "bg-green-50 text-green-600",
    purple: "bg-purple-50 text-purple-600",
    red: "bg-red-50 text-red-600",
  };
  return (
    <div className="bg-card border border-border rounded-2xl p-5">
      <div className={`w-10 h-10 rounded-xl flex items-center justify-center mb-3 ${colors[color]}`}>
        <Icon className="w-5 h-5" />
      </div>
      <p className="text-2xl font-bold">{value}</p>
      <p className="text-sm text-muted-foreground mt-0.5">{label}</p>
    </div>
  );
}

