import { useEffect, useState } from "react";
import { base44 } from "@/api/base44Client";
import { Swords, Trophy, MessageSquare } from "lucide-react";

export default function PortalSparring() {
  const [matches, setMatches] = useState([]);
  const [student, setStudent] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function load() {
      const me = await base44.auth.me();
      const students = await base44.entities.Student.filter({ email: me.email });
      const s = students[0];
      setStudent(s);
      if (s) {
        const allMatches = await base44.entities.SparringMatch.list("-date", 200);
        setMatches(allMatches.filter(m => m.student1_id === s.id || m.student2_id === s.id));
      }
      setLoading(false);
    }
    load();
  }, []);

  if (loading) return <div className="flex justify-center py-20"><div className="w-8 h-8 border-4 border-muted border-t-primary rounded-full animate-spin" /></div>;

  if (!student) return (
    <div className="w-full text-center py-16 text-muted-foreground">No student record linked to your account.</div>
  );

  const wins = matches.filter(m => m.winner_id === student.id).length;
  const draws = matches.filter(m => m.result === "draw").length;
  const losses = matches.length - wins - draws;

  return (
    <div className="w-full space-y-6">
      <div>
        <h1 className="text-3xl font-bold tracking-tight">Sparring History</h1>
        <p className="text-muted-foreground mt-1">Your match results and instructor feedback.</p>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-3 gap-4">
        <div className="bg-card border border-border rounded-2xl p-5 text-center">
          <p className="text-3xl font-bold text-green-600">{wins}</p>
          <p className="text-sm text-muted-foreground mt-1">Wins</p>
        </div>
        <div className="bg-card border border-border rounded-2xl p-5 text-center">
          <p className="text-3xl font-bold text-red-500">{losses}</p>
          <p className="text-sm text-muted-foreground mt-1">Losses</p>
        </div>
        <div className="bg-card border border-border rounded-2xl p-5 text-center">
          <p className="text-3xl font-bold text-muted-foreground">{draws}</p>
          <p className="text-sm text-muted-foreground mt-1">Draws</p>
        </div>
      </div>

      {/* Match list */}
      <div className="bg-card border border-border rounded-2xl overflow-hidden">
        <div className="px-5 py-3 border-b border-border bg-muted/30 flex items-center gap-2">
          <Swords className="w-4 h-4 text-muted-foreground" />
          <p className="font-semibold text-sm">All Matches ({matches.length})</p>
        </div>
        {matches.length === 0 ? (
          <div className="text-center py-12 text-muted-foreground">No sparring matches recorded yet.</div>
        ) : (
          <div className="divide-y divide-border">
            {matches.map(match => {
              const isStudent1 = match.student1_id === student.id;
              const opponent = isStudent1 ? match.student2_name : match.student1_name;
              const myResult = match.result === "draw" ? "draw" : match.winner_id === student.id ? "win" : "loss";
              const myFeedback = isStudent1 ? match.student1_feedback : match.student2_feedback;

              return (
                <div key={match.id} className="px-5 py-4">
                  <div className="flex items-center gap-3 flex-wrap">
                    <span className="text-xs text-muted-foreground w-20 flex-shrink-0">{match.date}</span>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 flex-wrap">
                        <Swords className="w-3.5 h-3.5 text-muted-foreground flex-shrink-0" />
                        <span className="text-sm font-medium">vs. {opponent}</span>
                      </div>
                    </div>
                    <span className={`text-xs px-3 py-1 rounded-full font-semibold flex-shrink-0 ${
                      myResult === "win" ? "bg-green-100 text-green-700" :
                      myResult === "loss" ? "bg-red-100 text-red-600" :
                      "bg-muted text-muted-foreground"
                    }`}>
                      {myResult === "win" ? "🏆 Win" : myResult === "loss" ? "Loss" : "Draw"}
                    </span>
                  </div>

                  {(match.instructor_feedback || myFeedback) && (
                    <div className="mt-2 ml-24 space-y-1.5">
                      {match.instructor_feedback && (
                        <div className="flex items-start gap-1.5 text-xs text-muted-foreground">
                          <MessageSquare className="w-3 h-3 mt-0.5 flex-shrink-0" />
                          <span className="italic">"{match.instructor_feedback}"</span>
                        </div>
                      )}
                      {myFeedback && (
                        <div className="flex items-start gap-1.5 text-xs">
                          <MessageSquare className="w-3 h-3 mt-0.5 text-primary flex-shrink-0" />
                          <span className="text-foreground italic">"{myFeedback}"</span>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

src/pages/Promotions.jsx:
import { useEffect, useState } from "react";
import { base44 } from "@/api/base44Client";
import { Award, CheckCircle, XCircle, Clock, GripVertical } from "lucide-react";
import { DragDropContext, Droppable, Draggable } from "@hello-pangea/dnd";
import { Button } from "@/components/ui/button";
import BeltBadge from "../components/BeltBadge";
import BeltProgressBar from "../components/BeltProgressBar";
import { DEFAULT_BELT_REQUIREMENTS, checkEligibility, getNextBelt, BELT_ORDER } from "../utils/beltUtils";
import { toast } from "sonner";

export default function Promotions() {
  const [students, setStudents] = useState([]);
  const [promotions, setPromotions] = useState([]);
  const [requirements, setRequirements] = useState(DEFAULT_BELT_REQUIREMENTS);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState("eligible");
  const [promoting, setPromoting] = useState(null);
  const [promoNote, setPromoNote] = useState("");
  // Pipeline state: { studentId -> "eligible" | "scheduled" | "promoted" }
  const [pipeline, setPipeline] = useState({});
  const [pipelineNotes, setPipelineNotes] = useState({});

  const load = async () => {
    const [s, p, br] = await Promise.all([
      base44.entities.Student.list(),
      base44.entities.Promotion.list("-promotion_date", 50),
      base44.entities.BeltRequirement.list(),
    ]);
    setStudents(s);
    setPromotions(p);
    if (br.length > 0) {
      const reqMap = {};
      br.forEach(r => { reqMap[r.belt] = r; });
      setRequirements(reqMap);
    }
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const eligible = students.filter(s => {
    const { eligible } = checkEligibility(s, requirements);
    return eligible && s.current_belt !== "Black";
  });

  const pipelineStudents = eligible; // all eligible students go into pipeline

  const onDragEnd = async (result) => {
    if (!result.destination) return;
    const studentId = result.draggableId;
    const dest = result.destination.droppableId;
    const student = students.find(s => s.id === studentId);
    if (!student) return;
    if (dest === "promoted") {
      setPromoting(student);
    } else {
      setPipeline(p => ({ ...p, [studentId]: dest }));
    }
  };

  const getPipelineCol = (studentId) => pipeline[studentId] || "eligible";

  const inProgress = students.filter(s => {
    const { eligible } = checkEligibility(s, requirements);
    return !eligible && s.current_belt !== "Black";
  });

  const handlePromote = async (student) => {
    const nextBelt = getNextBelt(student.current_belt);
    if (!nextBelt) return;

    await base44.entities.Promotion.create({
      student_id: student.id,
      student_name: student.full_name,
      from_belt: student.current_belt,
      to_belt: nextBelt,
      promotion_date: new Date().toISOString().split("T")[0],
      test_result: "pass",
      instructor_notes: promoNote,
      classes_completed: student.classes_in_current_belt || 0,
    });

    await base44.entities.Student.update(student.id, {
      current_belt: nextBelt,
      classes_in_current_belt: 0,
      stripes: 0,
      belt_start_date: new Date().toISOString().split("T")[0],
      eligible_for_testing: false,
      instructor_approved: false,
    });

    toast.success(`${student.full_name} promoted to ${nextBelt} Belt!`);
    setPromoting(null);
    setPromoNote("");
    load();
  };

  if (loading) return <div className="flex justify-center py-16"><div className="w-8 h-8 border-4 border-muted border-t-primary rounded-full animate-spin" /></div>;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold tracking-tight">Promotions</h1>
        <p className="text-muted-foreground mt-1">Track belt testing eligibility and record promotions.</p>
      </div>

      <div className="flex gap-2">
        {["eligible", "pipeline", "in_progress", "history"].map(t => (
          <button
            key={t}
            onClick={() => setTab(t)}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${tab === t ? "bg-primary text-primary-foreground" : "bg-card border border-border text-muted-foreground hover:text-foreground"}`}
          >
            {t === "eligible" ? `Eligible (${eligible.length})` : t === "pipeline" ? `Pipeline` : t === "in_progress" ? `In Progress (${inProgress.length})` : "History"}
          </button>
        ))}
      </div>

      {tab === "eligible" && (
        <div className="space-y-4">
          {eligible.length === 0 ? (
            <div className="bg-card border border-border rounded-2xl p-12 text-center text-muted-foreground">No students are currently eligible for promotion.</div>
          ) : eligible.map(student => {
            const nextBelt = getNextBelt(student.current_belt);
            const req = requirements[student.current_belt] || DEFAULT_BELT_REQUIREMENTS[student.current_belt];
            return (
              <div key={student.id} className="bg-card border border-border rounded-2xl p-5">
                <div className="flex items-start justify-between gap-4 flex-wrap">
                  <div className="flex items-center gap-3">
                    <div className="w-12 h-12 rounded-full bg-green-100 flex items-center justify-center font-bold text-green-700 text-lg">
                      {student.full_name?.charAt(0)}
                    </div>
                    <div>
                      <p className="font-semibold">{student.full_name}</p>
                      <div className="flex items-center gap-2 mt-1 flex-wrap">
                        <BeltBadge belt={student.current_belt} size="sm" />
                        <span className="text-muted-foreground text-xs">→</span>
                        {nextBelt && <BeltBadge belt={nextBelt} size="sm" />}
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="flex items-center gap-1 text-xs text-green-600 font-medium bg-green-100 px-3 py-1.5 rounded-full">
                      <CheckCircle className="w-3 h-3" /> Eligible
                    </span>
                    <Button size="sm" onClick={() => setPromoting(student)}>
                      <Award className="w-3.5 h-3.5 mr-1" /> Promote
                    </Button>
                  </div>
                </div>
                <div className="mt-4">
                  <BeltProgressBar student={student} requirement={req} />
                </div>
              </div>
            );
          })}
        </div>
      )}

      {tab === "in_progress" && (
        <div className="space-y-4">
          {inProgress.length === 0 ? (
            <div className="bg-card border border-border rounded-2xl p-12 text-center text-muted-foreground">All students are eligible or at black belt.</div>
          ) : inProgress.map(student => {
            const { reasons } = checkEligibility(student, requirements);
            const req = requirements[student.current_belt] || DEFAULT_BELT_REQUIREMENTS[student.current_belt];
            return (
              <div key={student.id} className="bg-card border border-border rounded-2xl p-5">
                <div className="flex items-center justify-between gap-4 flex-wrap mb-4">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full bg-muted flex items-center justify-center font-bold text-sm">
                      {student.full_name?.charAt(0)}
                    </div>
                    <div>
                      <p className="font-semibold">{student.full_name}</p>
                      <BeltBadge belt={student.current_belt} size="sm" />
                    </div>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {reasons.map((r, i) => (
                      <span key={i} className="text-xs bg-amber-100 text-amber-700 px-2 py-1 rounded-full flex items-center gap-1">
                        <Clock className="w-3 h-3" /> {r}
                      </span>
                    ))}
                  </div>
                </div>
                {req && <BeltProgressBar student={student} requirement={req} />}
              </div>
            );
          })}
        </div>
      )}

      {tab === "pipeline" && (
        <DragDropContext onDragEnd={onDragEnd}>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {[
              { id: "eligible", label: "Eligible — Not Yet Scheduled", color: "border-blue-300 bg-blue-50" },
              { id: "scheduled", label: "Scheduled for Test", color: "border-yellow-300 bg-yellow-50" },
              { id: "promoted", label: "Drag here to Promote ✓", color: "border-green-300 bg-green-50" },
            ].map(col => (
              <div key={col.id} className={`rounded-2xl border-2 ${col.color} p-3 min-h-48`}>
                <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-3 px-1">{col.label}</p>
                <Droppable droppableId={col.id}>
                  {(provided, snapshot) => (
                    <div ref={provided.innerRef} {...provided.droppableProps}
                      className={`space-y-2 min-h-16 rounded-xl transition-colors ${snapshot.isDraggingOver ? "bg-white/60" : ""}`}>
                      {pipelineStudents.filter(s => getPipelineCol(s.id) === col.id).map((student, idx) => {
                        const nextBelt = getNextBelt(student.current_belt);
                        return (
                          <Draggable key={student.id} draggableId={student.id} index={idx}>
                            {(provided, snapshot) => (
                              <div ref={provided.innerRef} {...provided.draggableProps}
                                className={`bg-card border border-border rounded-xl p-3 flex items-center gap-2 shadow-sm ${snapshot.isDragging ? "shadow-lg ring-2 ring-primary/30" : ""}`}>
                                <span {...provided.dragHandleProps}>
                                  <GripVertical className="w-4 h-4 text-muted-foreground flex-shrink-0" />
                                </span>
                                <div className="flex-1 min-w-0">
                                  <p className="font-medium text-sm">{student.full_name}</p>
                                  <p className="text-xs text-muted-foreground">{student.current_belt} → {nextBelt}</p>
                                </div>
                              </div>
                            )}
                          </Draggable>
                        );
                      })}
                      {provided.placeholder}
                    </div>
                  )}
                </Droppable>
              </div>
            ))}
          </div>
          <p className="text-xs text-muted-foreground mt-2">Drag students between columns. Drop onto "Promote" to record a promotion.</p>
        </DragDropContext>
      )}

      {tab === "history" && (
        <div className="bg-card border border-border rounded-2xl overflow-hidden">
          {promotions.length === 0 ? (
            <div className="text-center py-12 text-muted-foreground">No promotions recorded yet.</div>
          ) : (
            <div className="divide-y divide-border">
              {promotions.map(p => (
                <div key={p.id} className="flex items-center gap-4 px-5 py-4 flex-wrap">
                  <div className="flex-1 min-w-0">
                    <p className="font-medium">{p.student_name}</p>
                    <p className="text-xs text-muted-foreground">{new Date(p.promotion_date).toLocaleDateString()}</p>
                  </div>
                  <div className="flex items-center gap-2">
                    <BeltBadge belt={p.from_belt} size="sm" />
                    <span className="text-muted-foreground">→</span>
                    <BeltBadge belt={p.to_belt} size="sm" />
                  </div>
                  <span className={`text-xs px-2 py-1 rounded-full font-medium ${p.test_result === "pass" ? "bg-green-100 text-green-700" : "bg-red-100 text-red-700"}`}>
                    {p.test_result}
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Promotion Modal */}
      {promoting && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-card border border-border rounded-2xl w-full max-w-md p-6">
            <h3 className="font-semibold text-lg mb-1">Confirm Promotion</h3>
            <p className="text-muted-foreground text-sm mb-4">
              Promote <strong>{promoting.full_name}</strong> from <strong>{promoting.current_belt}</strong> to <strong>{getNextBelt(promoting.current_belt)}</strong> Belt?
            </p>
            <textarea
              placeholder="Add notes (optional)..."
              value={promoNote}
              onChange={e => setPromoNote(e.target.value)}
              className="w-full rounded-lg border border-input bg-background p-3 text-sm h-24 resize-none mb-4"
            />
            <div className="flex justify-end gap-3">
              <Button variant="outline" onClick={() => { setPromoting(null); setPromoNote(""); }}>Cancel</Button>
              <Button onClick={() => handlePromote(promoting)}>
                <Award className="w-4 h-4 mr-1.5" /> Confirm Promotion
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

src/pages/SparringMatches.jsx:
import { useEffect, useState } from "react";
import { base44 } from "@/api/base44Client";
import { Swords, Plus, Trophy, Minus, X, Search } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import BeltBadge from "../components/BeltBadge";
import { toast } from "sonner";

export default function SparringMatches() {
  const [matches, setMatches] = useState([]);
  const [students, setStudents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [search, setSearch] = useState("");
  const [form, setForm] = useState({
    date: new Date().toISOString().split("T")[0],
    student1_id: "", student2_id: "",
    result: "draw",
    instructor_feedback: "", student1_feedback: "", student2_feedback: "",
  });

  const load = async () => {
    const [m, s] = await Promise.all([
      base44.entities.SparringMatch.list("-date", 200),
      base44.entities.Student.list(),
    ]);
    setMatches(m);
    setStudents(s);
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const handleCreate = async () => {
    const s1 = students.find(s => s.id === form.student1_id);
    const s2 = students.find(s => s.id === form.student2_id);
    if (!s1 || !s2) return toast.error("Select both students");
    if (s1.id === s2.id) return toast.error("Students must be different");

    let winner_id = null, winner_name = null;
    if (form.result === "student1_wins") { winner_id = s1.id; winner_name = s1.full_name; }
    if (form.result === "student2_wins") { winner_id = s2.id; winner_name = s2.full_name; }

    await base44.entities.SparringMatch.create({
      ...form,
      student1_name: s1.full_name, student1_belt: s1.current_belt,
      student2_name: s2.full_name, student2_belt: s2.current_belt,
      winner_id, winner_name,
    });
    toast.success("Match logged!");
    setShowForm(false);
    setForm({ date: new Date().toISOString().split("T")[0], student1_id: "", student2_id: "", result: "draw", instructor_feedback: "", student1_feedback: "", student2_feedback: "" });
    load();
  };

  // Stats per student
  const getStats = (studentId) => {
    const relevant = matches.filter(m => m.student1_id === studentId || m.student2_id === studentId);
    const wins = relevant.filter(m => m.winner_id === studentId).length;
    const draws = relevant.filter(m => m.result === "draw").length;
    const losses = relevant.length - wins - draws;
    return { wins, losses, draws, total: relevant.length };
  };

  const filtered = matches.filter(m =>
    m.student1_name?.toLowerCase().includes(search.toLowerCase()) ||
    m.student2_name?.toLowerCase().includes(search.toLowerCase())
  );

  if (loading) return <div className="flex justify-center py-16"><div className="w-8 h-8 border-4 border-muted border-t-primary rounded-full animate-spin" /></div>;

  // Leaderboard: students with matches
  const studentIds = [...new Set(matches.flatMap(m => [m.student1_id, m.student2_id]).filter(Boolean))];
  const leaderboard = studentIds
    .map(id => ({ student: students.find(s => s.id === id), ...getStats(id) }))
    .filter(x => x.student)
    .sort((a, b) => b.wins - a.wins || a.losses - b.losses);

  return (
    <div className="space-y-6 w-full">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Sparring Matches</h1>
          <p className="text-muted-foreground mt-1">Log practice matches and track student win/loss records.</p>
        </div>
        <Button onClick={() => setShowForm(true)} className="gap-2"><Plus className="w-4 h-4" /> Log Match</Button>
      </div>

      {/* Leaderboard */}
      {leaderboard.length > 0 && (
        <div className="bg-card border border-border rounded-2xl overflow-hidden">
          <div className="px-5 py-3 border-b border-border bg-muted/30 flex items-center gap-2">
            <Trophy className="w-4 h-4 text-amber-500" />
            <p className="font-semibold text-sm">Leaderboard</p>
          </div>
          <div className="divide-y divide-border">
            {leaderboard.slice(0, 10).map(({ student, wins, losses, draws, total }, idx) => (
              <div key={student.id} className="flex items-center gap-4 px-5 py-3 flex-wrap">
                <span className="text-lg font-bold text-muted-foreground w-6 flex-shrink-0">#{idx + 1}</span>
                <div className="w-9 h-9 rounded-full bg-primary/10 flex items-center justify-center font-bold text-primary text-sm flex-shrink-0">
                  {student.full_name?.charAt(0)}
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-medium">{student.full_name}</p>
                  <BeltBadge belt={student.current_belt} size="sm" />
                </div>
                <div className="flex gap-4 text-sm flex-shrink-0">
                  <span className="text-green-600 font-semibold">{wins}W</span>
                  <span className="text-red-500 font-semibold">{losses}L</span>
                  <span className="text-muted-foreground">{draws}D</span>
                  <span className="text-muted-foreground text-xs">{total} matches</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Match History */}
      <div>
        <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
          <h2 className="font-semibold">Match History</h2>
          <div className="relative max-w-xs w-full">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input placeholder="Search by student..." className="pl-9" value={search} onChange={e => setSearch(e.target.value)} />
          </div>
        </div>
        <div className="bg-card border border-border rounded-2xl overflow-hidden">
          {filtered.length === 0 ? (
            <div className="text-center py-12 text-muted-foreground">No matches recorded yet.</div>
          ) : (
            <div className="divide-y divide-border">
              {filtered.map(match => (
                <div key={match.id} className="px-5 py-4">
                  <div className="flex items-center gap-3 flex-wrap">
                    <span className="text-xs text-muted-foreground w-20 flex-shrink-0">{match.date}</span>
                    <div className="flex-1 flex items-center gap-2 flex-wrap">
                      <span className={`font-medium text-sm ${match.result === "student1_wins" ? "text-green-600" : match.result === "student2_wins" ? "text-red-500" : ""}`}>
                        {match.student1_name}
                      </span>
                      <span className="text-xs text-muted-foreground">
                        {match.result === "draw" ? "drew with" : match.result === "student1_wins" ? "beat" : "lost to"}
                      </span>
                      <span className={`font-medium text-sm ${match.result === "student2_wins" ? "text-green-600" : match.result === "student1_wins" ? "text-red-500" : ""}`}>
                        {match.student2_name}
                      </span>
                    </div>
                    {match.result === "draw" ? (
                      <span className="text-xs bg-muted text-muted-foreground px-2 py-0.5 rounded-full font-medium">Draw</span>
                    ) : (
                      <span className="text-xs bg-green-100 text-green-700 px-2 py-0.5 rounded-full font-medium flex items-center gap-1">
                        <Trophy className="w-3 h-3" /> {match.winner_name}
                      </span>
                    )}
                  </div>
                  {match.instructor_feedback && (
                    <p className="text-xs text-muted-foreground mt-1.5 ml-24 italic">"{match.instructor_feedback}"</p>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Log Match Modal */}
      {showForm && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-card border border-border rounded-2xl w-full max-w-lg max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between p-6 border-b border-border sticky top-0 bg-card">
              <h3 className="font-semibold text-lg">Log Sparring Match</h3>
              <button onClick={() => setShowForm(false)} className="p-2 hover:bg-muted rounded-lg"><X className="w-4 h-4" /></button>
            </div>
            <div className="p-6 space-y-4">
              <div>
                <Label>Date</Label>
                <Input type="date" value={form.date} onChange={e => set("date", e.target.value)} className="mt-1" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Student 1</Label>
                  <Select value={form.student1_id} onValueChange={v => set("student1_id", v)}>
                    <SelectTrigger className="mt-1"><SelectValue placeholder="Select..." /></SelectTrigger>
                    <SelectContent>{students.map(s => <SelectItem key={s.id} value={s.id}>{s.full_name}</SelectItem>)}</SelectContent>
                  </Select>
                </div>
                <div>
                  <Label>Student 2</Label>
                  <Select value={form.student2_id} onValueChange={v => set("student2_id", v)}>
                    <SelectTrigger className="mt-1"><SelectValue placeholder="Select..." /></SelectTrigger>
                    <SelectContent>{students.map(s => <SelectItem key={s.id} value={s.id}>{s.full_name}</SelectItem>)}</SelectContent>
                  </Select>
                </div>
              </div>
              <div>
                <Label>Result</Label>
                <Select value={form.result} onValueChange={v => set("result", v)}>
                  <SelectTrigger className="mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="draw">Draw</SelectItem>
                    <SelectItem value="student1_wins">{form.student1_id ? students.find(s => s.id === form.student1_id)?.full_name || "Student 1" : "Student 1"} wins</SelectItem>
                    <SelectItem value="student2_wins">{form.student2_id ? students.find(s => s.id === form.student2_id)?.full_name || "Student 2" : "Student 2"} wins</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>General Instructor Feedback</Label>
                <textarea value={form.instructor_feedback} onChange={e => set("instructor_feedback", e.target.value)}
                  className="mt-1 w-full rounded-lg border border-input bg-background p-3 text-sm h-20 resize-none" placeholder="Overall notes about the match..." />
              </div>
              <div>
                <Label>Feedback for {form.student1_id ? students.find(s => s.id === form.student1_id)?.full_name || "Student 1" : "Student 1"}</Label>
                <textarea value={form.student1_feedback} onChange={e => set("student1_feedback", e.target.value)}
                  className="mt-1 w-full rounded-lg border border-input bg-background p-3 text-sm h-16 resize-none" placeholder="Private feedback visible to this student..." />
              </div>
              <div>
                <Label>Feedback for {form.student2_id ? students.find(s => s.id === form.student2_id)?.full_name || "Student 2" : "Student 2"}</Label>
                <textarea value={form.student2_feedback} onChange={e => set("student2_feedback", e.target.value)}
                  className="mt-1 w-full rounded-lg border border-input bg-background p-3 text-sm h-16 resize-none" placeholder="Private feedback visible to this student..." />
              </div>
            </div>
            <div className="flex justify-end gap-3 px-6 pb-6">
              <Button variant="outline" onClick={() => setShowForm(false)}>Cancel</Button>
              <Button onClick={handleCreate} disabled={!form.student1_id || !form.student2_id}>
                <Swords className="w-4 h-4 mr-1.5" /> Log Match
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

